const { RangeTree } = require('./src/range-tree');
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const ri = n => Math.floor(rnd() * n);

for (let trial = 0; trial < 400; trial++) {
  const n = 1 + ri(64);
  const vals = Array.from({length: n}, () => Math.floor(rnd() * 2001) - 1000);
  const model = vals.slice();
  const tree = new RangeTree(vals);
  const chk = (a, b, msg) => { if (!Object.is(a, b)) throw new Error('trial ' + trial + ': ' + msg + ' got ' + a + ' want ' + b); };
  for (let op = 0; op < 300; op++) {
    const kind = ri(7);
    const l = ri(n + 1), r = l + ri(n + 1 - l);
    if (kind === 0) { const v = Math.floor(rnd() * 2001) - 1000; tree.assign(l, r, v); for (let i = l; i < r; i++) model[i] = v; }
    else if (kind === 1) { const v = Math.floor(rnd() * 2001) - 1000; tree.add(l, r, v); for (let i = l; i < r; i++) model[i] += v; }
    else if (kind === 2) chk(tree.sum(l, r), model.slice(l, r).reduce((a, b) => a + b, 0), 'sum(' + l + ',' + r + ')');
    else if (kind === 3) chk(tree.max(l, r), l === r ? -Infinity : Math.max(...model.slice(l, r)), 'max(' + l + ',' + r + ')');
    else if (kind === 4) { const i = ri(n); chk(tree.get(i), model[i], 'get(' + i + ')'); }
    else if (kind === 5) {
      const lo = ri(n + 1);
      const x = [-Infinity, Infinity, Math.floor(rnd() * 4001) - 2000][ri(3)];
      let want = -1; for (let i = lo; i < n; i++) if (model[i] >= x) { want = i; break; }
      chk(tree.firstAtLeast(lo, x), want, 'firstAtLeast(' + lo + ',' + x + ')');
    } else {
      const a = tree.toArray();
      chk(a.length, n, 'toArray length');
      for (let i = 0; i < n; i++) chk(a[i], model[i], 'toArray[' + i + ']');
      a[0] = 999999; // aliasing check
    }
  }
}

// error handling / edge cases
const t = new RangeTree([5]);
const throws = f => { try { f(); } catch (e) { if (e instanceof RangeError) return; } throw new Error('expected RangeError'); };
throws(() => new RangeTree([]));
throws(() => new RangeTree([1, NaN]));
throws(() => new RangeTree('abc'));
throws(() => t.sum(-1, 1)); throws(() => t.sum(0, 2)); throws(() => t.sum(1, 0)); throws(() => t.sum(0, 0.5));
throws(() => t.assign(0, 1, NaN)); throws(() => t.add(0, 0, Infinity)); // v checked even for empty range
throws(() => t.get(-1)); throws(() => t.get(1)); throws(() => t.get(0.5));
throws(() => t.firstAtLeast(-1, 0)); throws(() => t.firstAtLeast(2, 0)); throws(() => t.firstAtLeast(0, NaN));
t.add(0, 0, 7); // empty range no-op, but finite v required (already covered)
if (t.get(0) !== 5) throw new Error('empty-range add mutated value');
if (t.length !== 1) throw new Error('length');
if (t.assign(0, 1, 3) !== undefined || t.add(0, 1, 1) !== undefined) throw new Error('return value');
if (t.get(0) !== 4) throw new Error('assign/add');
